import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, -0.3, 0);

  // Load texture asset
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  const textureAsset = ctx.textureLoader.load(imageUrl);

  // Atlas region dimensions: 512x320 pixels
  // Aspect ratio: 1.6
  const aspectRatio = 512 / 320;
  const height = 1;
  const width = height * aspectRatio;

  // Create plane geometry sized to atlas aspect ratio
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material using TSL texture node
  const textureNode = texture(textureAsset);
  const material = new MeshBasicNodeMaterial({
    colorNode: textureNode,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create and add mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Initialize event handlers (none for this static element)
  group.userData.handlers = {};

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
